-- PT119-S3-Q14. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT119-S3-Q14$batch10$ AND q.stimulus=$batch10$Political scientist: The economies of a number of European countries are currently in severe difficulty. Germany is the only neighboring country that has the resources to resuscitate these economies. Therefore, Germany should begin aiding these economically troubled countries.$batch10$ AND q.prompt=$batch10$Which one of the following principles most helps to justify the political scientist's reasoning?$batch10$ AND q.correct_choice=$batch10$B$batch10$) THEN RAISE EXCEPTION 'Question changed: PT119-S3-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT119-S3-Q14$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT119-S3-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT119-S3-Q14$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Germany should begin aiding the economically troubled European countries.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Several neighboring countries' economies are in severe difficulty, and Germany is the only neighbor with the resources to revive them.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The political scientist moves from "only Germany can help" to "Germany should help." The principle has to put "alone has the capacity" on the left and "should use it" on the right.$batch10$), (3, $batch10$Goal$batch10$, $batch10$A nation that alone can revive its neighbors' economies should do so.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT119-S3-Q14$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This starts with a nation that alone has an obligation, which is what the argument needs to establish. It also only limits who else should give aid.$batch10$), ($batch10$B$batch10$, $batch10$Germany alone has the capacity to revive its neighbors' economies. This principle says a nation in that position should use it, so Germany should begin aiding them.$batch10$), ($batch10$C$batch10$, $batch10$Nothing says Germany can afford to help only a few nations. This principle doesn't match the facts.$batch10$), ($batch10$D$batch10$, $batch10$"Only nations that alone have the capacity should exercise it" makes having that capacity necessary for acting, not sufficient. It tells us who may act, not that Germany must. Picked by 9 percent, so watch for "only" turning a trigger into a requirement.$batch10$), ($batch10$E$batch10$, $batch10$Like D, "only" makes the condition necessary. It also depends on Germany being able to aid just a few nations, which we aren't told.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT119-S3-Q14$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
